import React, { useEffect, useRef } from 'react'
import * as THREE from 'three'

/**
 * Lightweight 3D hub (Three.js). Portals fire onPortal('shop' | 'play').
 * WASD / arrows move; click a glowing portal to enter.
 */
const VerseHub = ({ onPortal }) => {
  const mountRef = useRef(null)
  const onPortalRef = useRef(onPortal)
  onPortalRef.current = onPortal

  useEffect(() => {
    const mount = mountRef.current
    if (!mount) return undefined

    const width = mount.clientWidth || window.innerWidth
    const height = mount.clientHeight || window.innerHeight

    const scene = new THREE.Scene()
    scene.background = new THREE.Color(0x05010f)
    scene.fog = new THREE.FogExp2(0x0a0518, 0.045)

    const camera = new THREE.PerspectiveCamera(60, width / height, 0.1, 200)
    camera.position.set(0, 1.6, 8)

    const renderer = new THREE.WebGLRenderer({ antialias: true, alpha: false })
    renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, 2))
    renderer.setSize(width, height)
    mount.appendChild(renderer.domElement)

    // Lights
    scene.add(new THREE.AmbientLight(0x6644aa, 0.55))
    const key = new THREE.DirectionalLight(0x80eaff, 0.85)
    key.position.set(4, 10, 6)
    scene.add(key)
    const rim = new THREE.PointLight(0xff6ec7, 1.2, 40)
    rim.position.set(-6, 4, -4)
    scene.add(rim)

    // Floor
    const floor = new THREE.Mesh(
      new THREE.CircleGeometry(18, 64),
      new THREE.MeshStandardMaterial({
        color: 0x12081f,
        metalness: 0.35,
        roughness: 0.55,
      }),
    )
    floor.rotation.x = -Math.PI / 2
    floor.receiveShadow = true
    scene.add(floor)

    const ring = new THREE.Mesh(
      new THREE.RingGeometry(4.2, 4.45, 64),
      new THREE.MeshBasicMaterial({
        color: 0x80eaff,
        transparent: true,
        opacity: 0.45,
        side: THREE.DoubleSide,
      }),
    )
    ring.rotation.x = -Math.PI / 2
    ring.position.y = 0.02
    scene.add(ring)

    // Center plinth
    const plinth = new THREE.Mesh(
      new THREE.CylinderGeometry(1.1, 1.35, 0.35, 32),
      new THREE.MeshStandardMaterial({
        color: 0x2a1450,
        metalness: 0.6,
        roughness: 0.35,
        emissive: 0x1a0840,
      }),
    )
    plinth.position.y = 0.18
    scene.add(plinth)

    const makePortal = (label, color, x, z) => {
      const group = new THREE.Group()
      group.position.set(x, 0, z)
      group.userData = { portal: label }

      const frame = new THREE.Mesh(
        new THREE.TorusGeometry(1.35, 0.12, 16, 48),
        new THREE.MeshStandardMaterial({
          color,
          emissive: color,
          emissiveIntensity: 0.65,
          metalness: 0.4,
          roughness: 0.3,
        }),
      )
      frame.rotation.y = Math.PI / 2
      frame.position.y = 1.55
      group.add(frame)

      const gate = new THREE.Mesh(
        new THREE.PlaneGeometry(2.1, 2.8),
        new THREE.MeshBasicMaterial({
          color,
          transparent: true,
          opacity: 0.22,
          side: THREE.DoubleSide,
        }),
      )
      gate.position.y = 1.55
      gate.rotation.y = Math.PI / 2
      gate.userData = { portal: label, isGate: true }
      group.add(gate)

      // Pedestal label sprite
      const canvas = document.createElement('canvas')
      canvas.width = 512
      canvas.height = 128
      const ctx = canvas.getContext('2d')
      ctx.fillStyle = 'rgba(0,0,0,0)'
      ctx.clearRect(0, 0, 512, 128)
      ctx.font = 'bold 48px Chakra Petch, Segoe UI, sans-serif'
      ctx.textAlign = 'center'
      ctx.fillStyle = '#f4f0ff'
      ctx.shadowColor = color
      ctx.shadowBlur = 18
      ctx.fillText(label === 'shop' ? 'GAME SHOP' : 'ONLINE GAMES', 256, 80)
      const tex = new THREE.CanvasTexture(canvas)
      const sprite = new THREE.Sprite(
        new THREE.SpriteMaterial({ map: tex, transparent: true }),
      )
      sprite.scale.set(3.2, 0.8, 1)
      sprite.position.set(0, 3.35, 0)
      group.add(sprite)

      scene.add(group)
      return { group, frame, gate }
    }

    const shopPortal = makePortal('shop', 0xff6ec7, -5.5, -3.5)
    const playPortal = makePortal('play', 0x80eaff, 5.5, -3.5)

    // Soft pillars for depth
    ;[-8, 8].forEach((x) => {
      const col = new THREE.Mesh(
        new THREE.CylinderGeometry(0.35, 0.45, 6, 12),
        new THREE.MeshStandardMaterial({
          color: 0x1a0a30,
          emissive: 0x301060,
          emissiveIntensity: 0.25,
        }),
      )
      col.position.set(x, 3, -8)
      scene.add(col)
    })

    // Player proxy (simple capsule-ish)
    const player = new THREE.Group()
    const body = new THREE.Mesh(
      new THREE.CapsuleGeometry(0.35, 0.7, 4, 8),
      new THREE.MeshStandardMaterial({
        color: 0xe8e0ff,
        emissive: 0x402080,
        emissiveIntensity: 0.2,
      }),
    )
    body.position.y = 1.05
    player.add(body)
    scene.add(player)

    const keys = Object.create(null)
    const onKey = (e, down) => {
      keys[e.code] = down
    }
    const keyDown = (e) => onKey(e, true)
    const keyUp = (e) => onKey(e, false)
    window.addEventListener('keydown', keyDown)
    window.addEventListener('keyup', keyUp)

    const raycaster = new THREE.Raycaster()
    const pointer = new THREE.Vector2()
    const clickable = [shopPortal.gate, playPortal.gate]

    let lastEnter = 0
    const tryEnterPortal = (portal) => {
      if (!portal || !onPortalRef.current) return
      const now = performance.now()
      if (now - lastEnter < 800) return
      lastEnter = now
      onPortalRef.current(portal)
    }

    const onClick = (event) => {
      const rect = renderer.domElement.getBoundingClientRect()
      pointer.x = ((event.clientX - rect.left) / rect.width) * 2 - 1
      pointer.y = -((event.clientY - rect.top) / rect.height) * 2 + 1
      raycaster.setFromCamera(pointer, camera)
      const hits = raycaster.intersectObjects(clickable, false)
      if (hits[0] && hits[0].object.userData.portal) {
        tryEnterPortal(hits[0].object.userData.portal)
      }
    }
    renderer.domElement.addEventListener('click', onClick)

    const clock = new THREE.Clock()
    let frameId = 0
    const velocity = new THREE.Vector3()
    const dir = new THREE.Vector3()

    const animate = () => {
      frameId = requestAnimationFrame(animate)
      const dt = Math.min(clock.getDelta(), 0.05)
      const t = clock.elapsedTime

      shopPortal.frame.rotation.z = t * 0.4
      playPortal.frame.rotation.z = -t * 0.35
      shopPortal.gate.material.opacity = 0.18 + Math.sin(t * 2) * 0.06
      playPortal.gate.material.opacity = 0.18 + Math.cos(t * 2) * 0.06
      ring.rotation.z = t * 0.15

      dir.set(0, 0, 0)
      if (keys.KeyW || keys.ArrowUp) dir.z -= 1
      if (keys.KeyS || keys.ArrowDown) dir.z += 1
      if (keys.KeyA || keys.ArrowLeft) dir.x -= 1
      if (keys.KeyD || keys.ArrowRight) dir.x += 1
      if (dir.lengthSq() > 0) {
        dir.normalize()
        velocity.x = dir.x * 4.5
        velocity.z = dir.z * 4.5
      } else {
        velocity.x *= 0.85
        velocity.z *= 0.85
      }
      player.position.x += velocity.x * dt
      player.position.z += velocity.z * dt
      // Stay on plaza
      const lim = 10
      player.position.x = Math.max(-lim, Math.min(lim, player.position.x))
      player.position.z = Math.max(-lim, Math.min(lim, player.position.z))

      // Camera follow
      const camTarget = new THREE.Vector3(
        player.position.x,
        1.6,
        player.position.z + 6.5,
      )
      camera.position.lerp(camTarget, 0.08)
      camera.lookAt(player.position.x, 1.2, player.position.z - 2)

      // Proximity enter
      ;[shopPortal, playPortal].forEach((p) => {
        const d = player.position.distanceTo(p.group.position)
        if (d < 1.85 && (keys.KeyE || keys.Enter)) {
          tryEnterPortal(p.group.userData.portal)
          keys.KeyE = false
          keys.Enter = false
        }
      })

      renderer.render(scene, camera)
    }
    animate()

    const onResize = () => {
      const w = mount.clientWidth || window.innerWidth
      const h = mount.clientHeight || window.innerHeight
      camera.aspect = w / h
      camera.updateProjectionMatrix()
      renderer.setSize(w, h)
    }
    window.addEventListener('resize', onResize)

    return () => {
      cancelAnimationFrame(frameId)
      window.removeEventListener('keydown', keyDown)
      window.removeEventListener('keyup', keyUp)
      window.removeEventListener('resize', onResize)
      renderer.domElement.removeEventListener('click', onClick)
      renderer.dispose()
      if (renderer.domElement.parentNode === mount) {
        mount.removeChild(renderer.domElement)
      }
    }
  }, [])

  return <div ref={mountRef} style={{ width: '100%', height: '100%' }} />
}

export default VerseHub
